\node at (2.575, 0) {$\scriptstyle a_2$};
\node at (3.5, -.9) {$\scriptstyle b_1$};
\node at (3.5, .85) {$\scriptstyle c_1$};
\node at (4.45, 0) {$\scriptstyle d_2$};
\node[cyan] at (2.1, .2) {$\scriptstyle e$};
