}\right)
=
\frac{1}{D_\cC^2} \sum_{c \in \Irr(\cC)} d_c
\tikzmath{
\draw (-.75, .5) -- (.75, .5);
\draw (-.5, .75) -- (-.5, -.75);
\draw (-.75, -.5) -- (.75, -.5);
\draw (.5, .75) -- (.5, -.75);
\node[gray] at (0, 0) {$\scriptstyle \times$};
\draw[rufous] (0, 0) circle (.4);
\node[rufous] at (.275, 0) {$\scriptstyle c$};
}\, ,
\end{equation}
where $D_\cC$ denotes the global dimension of $\cC$.
To interpret the diagram on the right, we use the fusion relation 
\begin{equation}
\label{eq:FusionRelation}
\tikzmath{
\draw (0, 0) -- (0, 1);
\draw (.25, 0) -- (.25, 1);
\node at (0, -.15) {$\scriptstyle a$};
\node at (.25, -.15) {$\scriptstyle b$};
}
=
\sum_{c \in \Irr(\cC)}
\frac{\sqrt{d_c}}{\sqrt{d_a d_b}}
\tikzmath{
